package com.shopsphere.web;
import com.shopsphere.dao.AdminOrderDAO;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;
@WebServlet("/admin/orders") public class AdminOrderServlet extends HttpServlet{private final AdminOrderDAO dao=new AdminOrderDAO();protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{try{q.setAttribute("orders",dao.findAll());q.getRequestDispatcher("/WEB-INF/views/admin/orders.jsp").forward(q,p);}catch(Exception e){throw new ServletException("Unable to load orders",e);}}protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{try{int id=Integer.parseInt(q.getParameter("orderId"));String s=q.getParameter("status");if(s==null)throw new IllegalArgumentException();dao.updateStatus(id,s.toUpperCase());p.sendRedirect(q.getContextPath()+"/admin/orders");}catch(IllegalArgumentException e){p.sendError(400,"Invalid order status or order id");}catch(Exception e){throw new ServletException("Unable to update order",e);}}}
